const D = { density:.5, energy:.55, hue:32, speed:1, scale:1, x:.5, y:.5, style:'mirage', act:'drift', seed:0, dunes:4 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), ez=t=>{t=clp(t,0,1);return t*t*(3-2*t);}, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const H=md(P.hue,360);
const style=P.style;
const thermal=style==='thermal', blueprint=style==='blueprint', riso=style==='riso', nocturne=style==='nocturne';
const en=clp(P.energy,0,1)*(.45+.6*K.intensity);
const dens=clp(P.density,0,1);
const W=width, Ht=height, u=Math.min(W,Ht);
const hzY=Ht*0.52;

// ---- static base buffer keyed on size + seed + style ----
const key=W+'x'+Ht+'|'+P.seed+'|'+style+'|'+Math.round(P.dunes);
if(!S.bg || S.key!==key){
  S.key=key;
  const g=createGraphics(W,Ht); g.colorMode(HSB,360,100,100,100); g.noStroke();
  // SKY
  for(let y=0;y<hzY;y++){
    const t=y/hzY; let sh,ss,sb;
    if(thermal){ sh=md(280-t*260,360); ss=72; sb=14+t*66; }
    else if(nocturne){ sh=228; ss=clp(72-t*34,20,80); sb=7+t*10; }
    else if(blueprint){ sh=210; ss=58; sb=13+t*4; }
    else if(riso){ sh=(t<.5)?md(H+8,360):md(H+22,360); ss=52; sb=(t<.5)?72:84; }
    else { sh=md(H+(1-t)*10,360); ss=clp(72-t*44,18,80); sb=76+t*20; }
    g.fill(sh,ss,sb); g.rect(0,y,W,1);
  }
  // SUN / MOON disk
  const sunx=W*(0.28+0.44*fr(7)), suny=hzY*(0.34+0.26*fr(11));
  if(nocturne){ g.fill(48,12,96); g.ellipse(sunx,suny,u*0.14,u*0.14); g.fill(48,10,80,50); g.ellipse(sunx,suny,u*0.2,u*0.2);
    // stars
    g.fill(0,0,100); for(let i=0;i<120;i++){ const x=fr(i*3.1)*W, y=fr(i*7.7)*hzY*0.9, s=(fr(i*2.3)*1.6+.4); g.fill(0,0,70+fr(i*5)*30,80); g.ellipse(x,y,s,s); }
  } else if(blueprint){ g.noFill(); g.stroke(198,40,92,70); g.strokeWeight(1.4); g.ellipse(sunx,suny,u*0.16,u*0.16); g.noStroke();
  } else if(thermal){ g.fill(58,90,100); g.ellipse(sunx,suny,u*0.16,u*0.16); g.fill(40,80,90,40); g.ellipse(sunx,suny,u*0.26,u*0.26);
  } else { g.fill(md(H+18,360),52,100); g.ellipse(sunx,suny,u*0.15,u*0.15); g.fill(md(H+18,360),30,100,45); g.ellipse(sunx,suny,u*0.24,u*0.24); }

  // DUNES — receding sine ridges
  const nD=Math.max(3,Math.min(6,Math.round(P.dunes)));
  for(let d=0;d<nD;d++){
    const dep=d/(nD-1);
    const yb=hzY + (Ht-hzY)*(d/nD)*0.9 + 6;
    const amp=(14+fr(d*9+1)*26)* (u/520);
    const wob=0.006+fr(d*4)*0.006;
    const ph=fr(d*13)*TAU;
    let dh,dsat,db;
    if(thermal){ dh=md(40-dep*40,360); dsat=88; db=42+dep*40; }
    else if(nocturne){ dh=230; dsat=44; db=6+dep*8; }
    else if(blueprint){ dh=200; dsat=0; db=0; }
    else if(riso){ dh=md(H+180*(d%2),360); dsat=58; db=44+dep*26; }
    else { dh=md(H-8+dep*4,360); dsat=clp(62-dep*20,18,80); db=64-dep*30; }
    if(blueprint){
      g.noFill(); g.stroke(198,46,90,55); g.strokeWeight(1.1);
      g.beginShape(); for(let x=0;x<=W;x+=14){ g.vertex(x, yb+Math.sin(x*wob+ph)*amp); } g.endShape(); g.noStroke();
      continue;
    }
    g.fill(dh,dsat,db);
    g.beginShape(); g.vertex(0,Ht); g.vertex(0,yb+22);
    for(let x=0;x<=W;x+=18){ g.vertex(x, yb+Math.sin(x*wob+ph)*amp); }
    g.vertex(W,Ht); g.endShape(CLOSE);
    // wind-ripple hatch on near dunes
    if(!riso && dep>0.4){ g.stroke(dh,dsat*0.7,db*0.6,40); g.strokeWeight(1);
      for(let x=0;x<W;x+=26){ const yy=yb+Math.sin(x*wob+ph)*amp+8+fr(x)*10; g.line(x,yy,x+16,yy+3); } g.noStroke(); }
  }
  // CACTI silhouettes (skip on blueprint -> schematic markers instead)
  const cn=5;
  for(let i=0;i<cn;i++){
    const cxp=W*(0.1+0.8*fr(i*17+3)), base=hzY+(Ht-hzY)*(0.42+fr(i*5)*0.3), hgt=(46+fr(i*31)*46)*(u/520);
    if(blueprint){ g.stroke(198,44,88,60); g.strokeWeight(1.1); g.noFill(); g.line(cxp,base,cxp,base-hgt); g.line(cxp,base-hgt*0.6,cxp-hgt*0.4,base-hgt*0.6); g.line(cxp-hgt*0.4,base-hgt*0.6,cxp-hgt*0.4,base-hgt*0.9); g.noStroke(); continue; }
    const ch=nocturne?150:(thermal?18:130), cs=nocturne?40:(thermal?90:64), cb=nocturne?5:(thermal?70:24);
    g.fill(ch,cs,cb);
    g.rect(cxp-4*(u/520),base-hgt,8*(u/520),hgt,3);
    g.rect(cxp-hgt*0.34,base-hgt*0.62,hgt*0.3,6*(u/520),3);
    g.rect(cxp-hgt*0.34,base-hgt*0.62-hgt*0.32,6*(u/520),hgt*0.32,3);
    g.rect(cxp+4*(u/520),base-hgt*0.5,hgt*0.3,6*(u/520),3);
    g.rect(cxp+hgt*0.28,base-hgt*0.5-hgt*0.26,6*(u/520),hgt*0.26,3);
  }
  S.bg=g;
  S.sun={x:W*0.5,y:hzY*0.5};
}
image(S.bg,0,0);

// ---- live animated layer ----
// time-of-day slow tint (also an act) — never re-phases, driven by K.t
let tod = frc(K.t*0.010 + K.section*0.02);
if(P.act==='diurnal') tod = frc(K.t*0.022);
const warm = Math.sin(tod*TAU); // -1..1
const dawnAmt = clp(0.5+0.5*warm,0,1);

// SUN GLOW pulse (additive)
if(!blueprint){
  const gx=W*(0.28+0.44*fr(7)), gy=hzY*(0.34+0.26*fr(11));
  const glow=(0.5+0.5*K.swell)*en + A.bass*0.7;
  push(); blendMode(ADD);
  const gr=u*(0.16+0.10*glow);
  fill(thermal?58:md(H+18,360), thermal?80:40, 100, 8+10*glow);
  ellipse(gx,gy,gr,gr);
  ellipse(gx,gy,gr*1.7,gr*1.7);
  pop();
}

// HEAT SHIMMER near horizon — wavy translucent bands rolling in real time
if(!nocturne){
  push(); blendMode(ADD);
  const bands=10; const shA=(0.5+0.6*en);
  for(let b=0;b<bands;b++){
    const yy=hzY - (b/bands)*hzY*0.32;
    const off=Math.sin(K.t*1.7 + b*0.9)*8*(u/520)*en;
    noFill(); stroke(thermal?30:md(H+10,360), 40, 100, 6*shA);
    strokeWeight(2.2*(u/520));
    beginShape();
    for(let x=0;x<=W;x+=22){ vertex(x, yy + Math.sin(x*0.02 + K.t*2.2 + b)*4*(u/520) + off); }
    endShape();
  }
  noStroke(); pop();
}

// DRIFTING SAND / DUST — continuous horizontal drift on K.t (motion floor)
const storm = P.act==='sandstorm';
const maxDust = Math.round((storm?260:150) * (0.25+dens));
const driftBase = (storm?0.16:0.05) + en*0.05;
const dustCol = nocturne? [40,20,70] : thermal? [30,70,95] : [md(H+6,360),42,96];
push(); blendMode(storm?BLEND:ADD);
for(let i=0;i<maxDust;i++){
  const layer=0.4+fr(i*2.1)*1.2;
  const x=md(fr(i*3.7)*W + K.t*driftBase*layer*W*0.12, W);
  const y=hzY*0.2 + fr(i*9.3)*(Ht-hzY*0.2);
  const s=(0.6+fr(i*5.5)*2.2)*(u/520)*(storm?1.7:1);
  const a=(storm?26:10)*(0.4+fr(i*1.3)*0.8)*(0.5+en);
  fill(dustCol[0],dustCol[1],dustCol[2], a);
  ellipse(x,y,s,s);
}
pop();

// TIME-OF-DAY WASH — big translucent overlay, slow evolution + keeps motion alive
push(); blendMode(BLEND);
const washH = nocturne?228 : (warm>0? md(H+8,360) : 210);
const washA = 6 + 10*Math.abs(warm) + (storm?10:0);
noStroke(); fill(washH, nocturne?50:38, nocturne?12:70, washA);
rect(0,0,W,hzY);
fill(washH, 40, nocturne?8:40, washA*0.7);
rect(0,hzY,W,Ht-hzY);
pop();

blendMode(BLEND);
